import { Router } from "express";
import { getAllConverSationUsers, getAllFriends, getCurrentUser, login, logOut, resetPassword, signup, updateProfile, } from "./controllers/userController.js";
import upload from "./lib/cloudinary.js";
import { editMessageFile, getAllMyMessages, getGroupMessages, getMessages, sendGroupMessage, sendMessage, } from "./controllers/messageController.js";
import { createGroup, getGroupMemeberLastMsgSeenId, updatelastMessageId, } from "./controllers/groupController.js";
import { saveFcmToken } from "./controllers/notificationTokenController.js";
import { acceptRequest, getPendingReuests, sidebarChatList, } from "./controllers/sidebarController.js";
import { emailOtpVerify, forgetPasswordEmailVerify, resendMailForgetPassword, resendMailVerify, } from "./controllers/emailController.js";
import { blockUser, getAllBlockedUsersByLoggedInUser, unBlockUser, } from "./controllers/blockController.js";
import { verifyToken } from "./authMiddleware/verifyToken.js";
const router = Router();
router.post("/signup", upload.single("image"), signup);
router.post("/login", login);
router.get("/getFriends/:id", getAllFriends);
router.get("/logedInUser/:id", getCurrentUser);
// router.post("/addMessage", addMessage);
router.post("/addMessage", upload.array("file"), sendMessage);
router.post("/addGroupMessage", upload.array("file"), sendGroupMessage);
router.get("/getMessages", getMessages);
router.get("/userConversations", getAllConverSationUsers);
router.get("/getAllMyMessages", getAllMyMessages);
router.put("/updateProfile", upload.single("image"), updateProfile);
router.post("/createGroup", upload.single("image"), createGroup);
router.post("/verifyEmailOtp", emailOtpVerify);
router.get("/getSidebarChatList", sidebarChatList);
router.get("/getGroupMessages", getGroupMessages);
router.put("/updateMemberLastMsgId", updatelastMessageId);
router.put("/updateMessageFile", upload.array("file"), editMessageFile);
router.post("/resendMailForgetPassword", resendMailForgetPassword);
router.post("/forgetPassword_EmailVerify", forgetPasswordEmailVerify);
router.get("/userLastMsgSeenDetail", getGroupMemeberLastMsgSeenId);
router.get("/getPendingRequest", getPendingReuests);
router.put("/acceptRequest", acceptRequest);
router.post("/resendMail", resendMailVerify);
router.post("/save-fcm-token", saveFcmToken);
router.post("/resetPassword", resetPassword);
router.post("/blockUser", blockUser);
router.delete("/unBlockUser", unBlockUser);
router.get("/getAllBlockedUsers", verifyToken, getAllBlockedUsersByLoggedInUser);
router.post("/logout", verifyToken, logOut);
export default router;
